    for ticker in ("UMLGX", "CREAX", "CRRVX", "CREYX", "CBALX", "CBMZX", "LBSAX"):
        body = client.get("/funds", params={"q": ticker}).json()
        tickers = [item["ticker"] for item in body["items"]]
