def test_wave_bb_boston_trust_leftover_dec31_2021_2024_fills_5y() -> None:
    records = BostonTrustSource().fetch(mode="fixture").records
    btbfx_2024_oi = next(
        row
        for row in records
        if row.ticker == "BTBFX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2024-12-31"
        and row.publication_stage == PublicationStage.final
        and row.amount is not None
    )
    assert btbfx_2024_oi.amount == Decimal("0.94")
    btbfx_2021_cg = next(
        row
        for row in records
        if row.ticker == "BTBFX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2021-12-31"
        and row.publication_stage == PublicationStage.final
        and row.amount is not None
    )
    assert btbfx_2021_cg.amount == Decimal("0.51")
    btmfx_2024_oi = next(
        row
        for row in records
        if row.ticker == "BTMFX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2024-12-31"
        and row.amount is not None
    )
    assert btmfx_2024_oi.amount == Decimal("0.15")
    wsefx_2024_cg = next(
        row
        for row in records
        if row.ticker == "WSEFX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2024-12-31"
        and row.amount is not None
    )
    assert wsefx_2024_cg.amount == Decimal("1.55")
    wsefx_2023_oi = next(
        row
        for row in records
        if row.ticker == "WSEFX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2023-12-31"
        and row.amount is not None
    )
    assert wsefx_2023_oi.amount == Decimal("0.24")
    # Class-level / identity-level — Midcap is not copied from Asset Management.
    assert btmfx_2024_oi.amount != btbfx_2024_oi.amount
    # Eric freeze — out-of-book Boston Trust tickers stay unattached.
    leaked = [
        row
        for row in records
        if row.ticker in WAVE_BB_BOSTON_TRUST_OUT_OF_BOOK
    ]
    assert leaked == []
    # 2025 stays on the existing paid PDF — not re-emitted from N-CSR.
    ncsr_late = [
        row
        for row in records
        if row.ticker in WAVE_BB_BOSTON_TRUST_LEFTOVER_5Y
        and row.as_of
        and row.as_of.year == 2025
        and row.source_url
        and "485bpos" in row.source_url
    ]
    assert ncsr_late == []
    for ticker in WAVE_BB_BOSTON_TRUST_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(records, ticker), ticker


