WAVE_BN_DWS_LEFTOVER_5Y = ("KGDAX",)
WAVE_BN_SIBLING_WALLS = ("KGDCX", "SGSCX", "KGDIX", "KGDZX")
WAVE_BN_NCSR_ACCESSION = "000008805325001132"
WAVE_BN_ALGER_RESERVED = WAVE_BH_ALGER_RESERVED


def test_wave_bn_dws_leftover_oct31_fills_5y() -> None:
    records = DwsSource().fetch(mode="fixture").records
    kgdax_2024_oi = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2024-10-31"
        and row.publication_stage == PublicationStage.final
        and row.amount is not None
    )
    assert kgdax_2024_oi.amount == Decimal("0.20")
    kgdax_2024_cg = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2024-10-31"
        and row.amount is not None
    )
    assert kgdax_2024_cg.amount == Decimal("1.26")
    kgdax_2023_cg = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2023-10-31"
        and row.amount is not None
    )
    assert kgdax_2023_cg.amount == Decimal("1.32")
    kgdax_2022_oi = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2022-10-31"
        and row.amount is not None
    )
    assert kgdax_2022_oi.amount == Decimal("0.07")
    kgdax_2022_cg = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2022-10-31"
        and row.amount is not None
    )
    assert kgdax_2022_cg.amount == Decimal("5.84")
    kgdax_2021_cg = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2021-10-31"
        and row.amount is not None
    )
    assert kgdax_2021_cg.amount == Decimal("0.13")
    # Issuer dash 2021 OI and printed $0.00* 2023 OI stay unmatched.
    kgdax_omitted_oi = [
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and row.as_of.year in {2021, 2023}
        and row.source_url
        and WAVE_BN_NCSR_ACCESSION in row.source_url
    ]
    assert kgdax_omitted_oi == []
    # Class-level — never sibling-copied onto Class C / S / Institutional / R6.
    ncsr_siblings = [
        row
        for row in records
        if row.ticker in WAVE_BN_SIBLING_WALLS
        and row.source_url
        and WAVE_BN_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_siblings == []
    # Sister WAVE BM / BL / BK / BI / BJ / BG leftovers are not re-emitted here.
    ncsr_reserved = [
        row
        for row in records
        if row.ticker
        in WAVE_BM_BAIRD_LEFTOVER_5Y
        + WAVE_BL_THRIVENT_LEFTOVER_5Y
        + WAVE_BK_DWS_LEFTOVER_5Y
        + WAVE_BI_DWS_LEFTOVER_5Y
        + WAVE_BJ_RIVERPARK_LEFTOVER_5Y
        + WAVE_BG_DWS_LEFTOVER_5Y
        and row.source_url
        and WAVE_BN_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_reserved == []
    # 2025 stays on the existing paid retail book — not re-emitted from N-CSR.
    ncsr_late = [
        row
        for row in records
        if row.ticker in WAVE_BN_DWS_LEFTOVER_5Y
        and row.as_of
        and row.as_of.year == 2025
        and row.source_url
        and WAVE_BN_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_late == []
    kgdax_2025 = next(
        row
        for row in records
        if row.ticker == "KGDAX"
        and row.estimate_type == EstimateType.long_term_capital_gains
        and row.ex_date
        and str(row.ex_date) == "2025-12-23"
        and row.publication_stage == PublicationStage.final
        and row.amount is not None
    )
    assert kgdax_2025.amount == Decimal("2.5269")
    for ticker in WAVE_BN_DWS_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(records, ticker), ticker
    # Keep sister WAVE BK / BI / BG DWS leftovers 5y on tip.
    for ticker in WAVE_BK_DWS_LEFTOVER_5Y + WAVE_BI_DWS_LEFTOVER_5Y + WAVE_BG_DWS_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(records, ticker), ticker
    # Keep sister WAVE BM Baird leftovers 5y on tip.
    baird = BairdSource().fetch(mode="fixture").records
    for ticker in WAVE_BM_BAIRD_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baird, ticker), ticker
    # Keep sister WAVE BL Thrivent leftovers 5y on tip.
    thrivent = ThriventSource().fetch(mode="fixture").records
    for ticker in WAVE_BL_THRIVENT_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(thrivent, ticker), ticker
    # Keep sister WAVE BJ RiverPark leftovers 5y on tip.
    riverpark = RiverparkSource().fetch(mode="fixture").records
    for ticker in WAVE_BJ_RIVERPARK_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(riverpark, ticker), ticker


def test_wave_bn_leftover_walls_stay_unmatched() -> None:
    dws = DwsSource().fetch(mode="fixture").records
    ncsr_siblings = [
        row
        for row in dws
        if row.ticker in WAVE_BN_SIBLING_WALLS
        and row.source_url
        and WAVE_BN_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_siblings == []
    ncsr_tickers = {
        row.ticker
        for row in dws
        if row.source_url and WAVE_BN_NCSR_ACCESSION in row.source_url
    }
    assert ncsr_tickers == set(WAVE_BN_DWS_LEFTOVER_5Y)
    # SUWAX / SDGAX / SZCAX / DCUAX FYE September 30 are not calendar-safe.
    assert 2021 not in _paid_lookback_years(dws, "SUWAX")
    assert 2021 not in _paid_lookback_years(dws, "SDGAX")
    assert 2021 not in _paid_lookback_years(dws, "SZCAX")
    assert 2021 not in _paid_lookback_years(dws, "DCUAX")
