WAVE_BO_DWS_LEFTOVER_5Y = ("KTRAX",)
WAVE_BO_SIBLING_WALLS = ("KTRCX", "KTRSX", "KTRIX", "KTRZX")
WAVE_BO_NCSR_ACCESSION = "000008805325001130"
WAVE_BO_ALGER_RESERVED = WAVE_BH_ALGER_RESERVED


def test_wave_bo_dws_leftover_oct31_fills_5y() -> None:
    records = DwsSource().fetch(mode="fixture").records
    ktrax_2024_oi = next(
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2024-10-31"
        and row.publication_stage == PublicationStage.final
        and row.amount is not None
    )
    assert ktrax_2024_oi.amount == Decimal("0.34")
    ktrax_2023_oi = next(
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2023-10-31"
        and row.amount is not None
    )
    assert ktrax_2023_oi.amount == Decimal("0.26")
    ktrax_2022_oi = next(
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2022-10-31"
        and row.amount is not None
    )
    assert ktrax_2022_oi.amount == Decimal("0.23")
    ktrax_2022_cg = next(
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and str(row.as_of) == "2022-10-31"
        and row.amount is not None
    )
    assert ktrax_2022_cg.amount == Decimal("0.80")
    ktrax_2021_oi = next(
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.ordinary_income
        and row.as_of
        and str(row.as_of) == "2021-10-31"
        and row.amount is not None
    )
    assert ktrax_2021_oi.amount == Decimal("0.22")
    # Issuer dash 2024 / 2023 / 2021 CG stay unmatched — never invent $0.
    ktrax_omitted_cg = [
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.total_capital_gains
        and row.as_of
        and row.as_of.year in {2021, 2023, 2024}
        and row.source_url
        and WAVE_BO_NCSR_ACCESSION in row.source_url
    ]
    assert ktrax_omitted_cg == []
    # Class-level — never sibling-copied onto Class C / S / Institutional / R6.
    ncsr_siblings = [
        row
        for row in records
        if row.ticker in WAVE_BO_SIBLING_WALLS
        and row.source_url
        and WAVE_BO_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_siblings == []
    # Sister WAVE BN / BM / BL / BK / BI / BJ / BG leftovers are not re-emitted here.
    ncsr_reserved = [
        row
        for row in records
        if row.ticker
        in WAVE_BN_DWS_LEFTOVER_5Y
        + WAVE_BM_BAIRD_LEFTOVER_5Y
        + WAVE_BL_THRIVENT_LEFTOVER_5Y
        + WAVE_BK_DWS_LEFTOVER_5Y
        + WAVE_BI_DWS_LEFTOVER_5Y
        + WAVE_BJ_RIVERPARK_LEFTOVER_5Y
        + WAVE_BG_DWS_LEFTOVER_5Y
        and row.source_url
        and WAVE_BO_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_reserved == []
    # 2025 stays on the existing paid retail book — not re-emitted from N-CSR.
    ncsr_late = [
        row
        for row in records
        if row.ticker in WAVE_BO_DWS_LEFTOVER_5Y
        and row.as_of
        and row.as_of.year == 2025
        and row.source_url
        and WAVE_BO_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_late == []
    ktrax_2025 = next(
        row
        for row in records
        if row.ticker == "KTRAX"
        and row.estimate_type == EstimateType.long_term_capital_gains
        and row.ex_date
        and str(row.ex_date) == "2025-12-15"
        and row.publication_stage == PublicationStage.final
        and row.amount is not None
    )
    assert ktrax_2025.amount == Decimal("0.1744")
    for ticker in WAVE_BO_DWS_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(records, ticker), ticker
    # Keep sister WAVE BN / BK / BI / BG DWS leftovers 5y on tip.
    for ticker in (
        WAVE_BN_DWS_LEFTOVER_5Y
        + WAVE_BK_DWS_LEFTOVER_5Y
        + WAVE_BI_DWS_LEFTOVER_5Y
        + WAVE_BG_DWS_LEFTOVER_5Y
    ):
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(records, ticker), ticker
    # Keep sister WAVE BM Baird leftovers 5y on tip.
    baird = BairdSource().fetch(mode="fixture").records
    for ticker in WAVE_BM_BAIRD_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baird, ticker), ticker
    # Keep sister WAVE BL Thrivent leftovers 5y on tip.
    thrivent = ThriventSource().fetch(mode="fixture").records
    for ticker in WAVE_BL_THRIVENT_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(thrivent, ticker), ticker
    # Keep sister WAVE BJ RiverPark leftovers 5y on tip.
    riverpark = RiverparkSource().fetch(mode="fixture").records
    for ticker in WAVE_BJ_RIVERPARK_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(riverpark, ticker), ticker


def test_wave_bo_leftover_walls_stay_unmatched() -> None:
    dws = DwsSource().fetch(mode="fixture").records
    ncsr_siblings = [
        row
        for row in dws
        if row.ticker in WAVE_BO_SIBLING_WALLS
        and row.source_url
        and WAVE_BO_NCSR_ACCESSION in row.source_url
    ]
    assert ncsr_siblings == []
    ncsr_tickers = {
        row.ticker
        for row in dws
        if row.source_url and WAVE_BO_NCSR_ACCESSION in row.source_url
    }
    assert ncsr_tickers == set(WAVE_BO_DWS_LEFTOVER_5Y)
    # SUWAX / SDGAX / SZCAX / DCUAX FYE September 30 are not calendar-safe.
    assert 2021 not in _paid_lookback_years(dws, "SUWAX")
    assert 2021 not in _paid_lookback_years(dws, "SDGAX")
    assert 2021 not in _paid_lookback_years(dws, "SZCAX")
    assert 2021 not in _paid_lookback_years(dws, "DCUAX")
    # DESAX / KDHAX ~November 30 are not calendar-safe.
    assert 2021 not in _paid_lookback_years(dws, "DESAX")
    assert 2021 not in _paid_lookback_years(dws, "KDHAX")
    # SUHAX FYE May 31 is not calendar-safe.
    assert 2021 not in _paid_lookback_years(dws, "SUHAX")
    # WAVE BN Oct 31 accession still does not emit KTRAX.
    ktrax_bn = [
        row
        for row in dws
        if row.ticker == "KTRAX"
        and row.source_url
        and WAVE_BN_NCSR_ACCESSION in row.source_url
    ]
    assert ktrax_bn == []
    # WAVE BO Oct 31 accession still does not emit KGDAX.
    kgdax_bo = [
        row
        for row in dws
        if row.ticker == "KGDAX"
        and row.source_url
        and WAVE_BO_NCSR_ACCESSION in row.source_url
    ]
    assert kgdax_bo == []
    # Xtrackers leftover 2021–2023 ICI siblings stay unmatched.
    assert 2021 not in _paid_lookback_years(dws, "DEEF")
    assert 2022 not in _paid_lookback_years(dws, "DEEF")
    assert 2023 not in _paid_lookback_years(dws, "DEEF")

    # Keep sister WAVE BN DWS Global Small Cap — KGDAX stays 5y on tip.
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(dws, "KGDAX")
    # Keep sister WAVE BM Baird — CCGIX / CCGSX / CCWIX / CCWSX stay 5y.
    baird = BairdSource().fetch(mode="fixture").records
    for ticker in WAVE_BM_BAIRD_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baird, ticker), ticker
    # Keep sister WAVE BL Thrivent leftovers 5y on tip.
    thrivent = ThriventSource().fetch(mode="fixture").records
    for ticker in WAVE_BL_THRIVENT_LEFTOVER_5Y:
        assert set(LOOKBACK_YEARS) <= _paid_lookback_years(thrivent, ticker), ticker
    # Keep sister WAVE BK DWS RREEF — TOLLX stays 5y on tip.
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(dws, "TOLLX")
    # Keep sister WAVE BI DWS — KTCAX stays 5y on tip.
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(dws, "KTCAX")
    # Keep sister WAVE BJ RiverPark — RWGIX / RWGFX stay 5y on tip.
    riverpark = RiverparkSource().fetch(mode="fixture").records
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(riverpark, "RWGIX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(riverpark, "RWGFX")
    # Keep sister WAVE BG DWS — BTIEX / SXPAX stay 5y on tip.
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(dws, "BTIEX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(dws, "SXPAX")
    # Keep sister WAVE BH TCW — TGDIX / TGVOX / TGCEX / TGPCX stay 5y on tip.
    tcw = TcwSource().fetch(mode="fixture").records
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(tcw, "TGDIX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(tcw, "TGVOX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(tcw, "TGCEX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(tcw, "TGPCX")
    # Keep sister WAVE BF Baillie — BGAKX / BINSX / BGESX / BSGPX stay 5y on tip.
    baillie = BaillieGiffordSource().fetch(mode="fixture").records
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baillie, "BGAKX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baillie, "BINSX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baillie, "BGESX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(baillie, "BSGPX")
    # Keep sister WAVE BE Driehaus — DMCRX / DVSMX / DNSMX stay 5y on tip.
    driehaus = DriehausSource().fetch(mode="fixture").records
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(driehaus, "DMCRX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(driehaus, "DVSMX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(driehaus, "DNSMX")
    # Keep sister WAVE BD LoCorr — LFMIX / LCSIX / LOTIX / LEQIX stay 5y on tip.
    locorr = LocorrSource().fetch(mode="fixture").records
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(locorr, "LFMIX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(locorr, "LCSIX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(locorr, "LOTIX")
    assert set(LOOKBACK_YEARS) <= _paid_lookback_years(locorr, "LEQIX")

    # Exclusive leftover — WAVE BO ticker stays disjoint from BN KGDAX /
    # BM Baird / BL Thrivent / BK TOLLX / BI / BJ / BH / BG / BF / BE / BD
    # books and Alger reserved leftovers.
    dws_bo = {row.ticker for row in dws if row.source_url and WAVE_BO_NCSR_ACCESSION in row.source_url}
    dws_bn = {row.ticker for row in dws if row.source_url and WAVE_BN_NCSR_ACCESSION in row.source_url}
    baird_tickers = {row.ticker for row in baird if row.ticker}
    thrivent_tickers = {row.ticker for row in thrivent if row.ticker}
    baillie_tickers = {row.ticker for row in baillie if row.ticker}
    driehaus_tickers = {row.ticker for row in driehaus if row.ticker}
    locorr_tickers = {row.ticker for row in locorr if row.ticker}
    tcw_tickers = {row.ticker for row in tcw if row.ticker}
    riverpark_tickers = {row.ticker for row in riverpark if row.ticker}
    alger = AlgerSource().fetch(mode="fixture").records
    alger_tickers = {row.ticker for row in alger if row.ticker}
    assert dws_bo == set(WAVE_BO_DWS_LEFTOVER_5Y)
    assert dws_bn == set(WAVE_BN_DWS_LEFTOVER_5Y)
    assert not dws_bo & dws_bn
    assert not dws_bo & set(WAVE_BN_DWS_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BM_BAIRD_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BL_THRIVENT_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BK_DWS_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BI_DWS_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BJ_RIVERPARK_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BG_DWS_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BH_TCW_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BF_BAILLIE_LEFTOVER_5Y)
    assert not dws_bo & set(WAVE_BF_DRIEHAUS_DISJOINT)
    assert not dws_bo & set(WAVE_BF_LOCORR_DISJOINT)
    assert not dws_bo & set(WAVE_BO_ALGER_RESERVED)
    assert not dws_bo & baird_tickers
    assert not dws_bo & thrivent_tickers
    assert not dws_bo & baillie_tickers
    assert not dws_bo & driehaus_tickers
    assert not dws_bo & locorr_tickers
    assert not dws_bo & tcw_tickers
    assert not dws_bo & riverpark_tickers
    assert not dws_bo & alger_tickers
