    assert fetched.status_code == 200, fetched.text
    assert fetched.json()["created"] > 0

    for ticker in WAVE_CC_PIONEER_LEFTOVER_5Y:
        body = client.get("/funds", params={"q": ticker}).json()
        tickers = [item["ticker"] for item in body["items"]]
