WAVE_CN_CD_DISJOINT = WAVE_CD_LAZARD_LEFTOVER_5Y
WAVE_CN_CB_DISJOINT = WAVE_CB_LAZARD_LEFTOVER_5Y
WAVE_CN_BY_DISJOINT = WAVE_BY_LAZARD_LEFTOVER_5Y
